use std::ops::Bound;

// Bound<&T> is the std vocabulary for [a], (a) and unbounded sides:
let window: (Bound<u32>, Bound<u32>) = (Bound::Included(10), Bound::Excluded(20));

// contains() is stable on ranges:
assert!((10..20).contains(&15));
assert!(!(10..20).contains(&20));

// Overlap is not: (10..).intersect(..20) and is_empty() are nightly APIs.
// Stable code compares start_bound/end_bound (or the endpoints) by hand.

